        this.db = db;
    }

    public void adjust(UUID id, int delta) {
        // The predicate prevents two simultaneous decrements from going below zero.
        int changed = db.update("update community set open_items = open_items + ? "
            + "where id = ? and open_items + cast(? as bigint) >= 0", delta, id, delta);
        if (changed != 1) {
            throw new IllegalStateException("Record missing or count would become negative");
        }
    }
}

